# pre = marker as seen at the pre-insertion pose, insert = marker as seen with the plug at the socket entrance.
# nudge_px moves the insertion target in the image (x right, y down) to fine-tune where the gripper ends up; marker_side_m is the printed size.
marker_side_m: 0.030
